        questions: [
          q("What is the genuine difference between git merge and git rebase?", ["They produce identical results always", "Merge creates a new merge commit preserving both branches' true history; rebase rewrites history by replaying commits onto the target branch for a clean, linear history", "Rebase is only used for deleting branches", "Merge always deletes the source branch"], 1, "Medium", "Merge preserves real, branching history via a merge commit; rebase rewrites commits onto a new base, producing linear history with no merge commit.", ["Git", "Merge vs Rebase"]),
          q("Why is rebasing a branch that others have already pulled genuinely risky?", ["Rebasing has no real risk in any scenario", "Rebase rewrites commit hashes, so anyone who already pulled the old commits will have a diverged, broken history relative to the rewritten branch", "Rebase permanently deletes all file contents", "Git prevents this scenario entirely, so it's never actually a risk"], 1, "Medium", "Since rebase creates new commits with new hashes, collaborators who already based work on the old commits face a genuinely painful history divergence.", ["Git", "Rebase"]),
          q("What causes a merge conflict?", ["Two branches modifying the same lines of the same file in genuinely different, irreconcilable ways", "Simply having more than one branch in a repository", "Committing too frequently", "Using git push instead of git commit"], 0, "Easy", "Git can only auto-merge non-overlapping changes - conflicting edits to the same lines require manual resolution.", ["Git", "Merge Conflicts"]),
          q("What is the correct way to resolve a merge conflict?", ["Delete one side's changes arbitrarily without reading either version", "Read both conflicting versions, understand each one's intent, and manually write the genuinely correct combined result", "Leave both conflict marker blocks concatenated together in the file", "Always keep only your own local changes automatically"], 1, "Medium", "Correct resolution requires genuinely understanding both changes' intent, not a mechanical pick-one-side shortcut.", ["Git", "Merge Conflicts"]),
          q("What is the primary purpose of a pull request in a team git workflow?", ["To immediately merge code with no review at all", "To provide a structured place for code review, discussion, and CI checks before code reaches the shared branch", "To permanently delete a feature branch", "To rename a repository"], 1, "Easy", "A pull request's real value is catching issues via review/CI before code lands in the shared branch, not merging itself.", ["Git", "Pull Requests"]),
          q("What does 'git clone' do?", ["Creates a completely new, empty repository", "Creates a full local copy of a remote repository, including its entire commit history", "Deletes a remote repository", "Only copies the latest commit, discarding history"], 1, "Easy", "git clone copies the entire repository (all branches and full history) from a remote source to your local machine.", ["Git", "Basics"]),
          q("What is the difference between 'git fetch' and 'git pull'?", ["They are exactly identical commands", "git fetch downloads remote changes without merging them into your local branch; git pull fetches AND merges in one step", "git pull only works on the main branch", "git fetch deletes local changes"], 1, "Medium", "fetch is the safer, two-step-friendly download-only operation; pull combines fetch with an automatic merge/rebase.", ["Git", "Fetch vs Pull"]),
        ],
