const companyRef = await db.collection("companies").add({
  name: "Knowvation Learnings",
  ctc: "3.5 - 6 LPA (Software Engineer Trainee, band depends on role and performance)",
  difficulty: "Medium",
  description: "An ed-tech and software services company building learning platforms and enterprise web applications - hiring for roles centered on the Java/Spring Boot backend and React frontend stack, with strong emphasis on genuine, hands-on project understanding over rote framework memorization.",
  eligibility: "B.E./B.Tech/MCA/M.Sc in CS/IT/Electronics-adjacent branches. Minimum 60% or 6 CGPA across Class 10, Class 12, and UG, with no standing backlogs at the time of interview.",
  hiringOverview: "Candidates go through a Technical Screening (Java/OOP/Collections MCQs), a Coding Round (output-prediction, DSA concepts, SQL), a Technical Interview (Spring Boot, REST, React, Git, resume deep-dive), and finally an HR Discussion - see the Prep Roadmap and round-by-round breakdown below for full detail.",
  resources: [{ title: "STAR Method Guide", url: "https://www.themuse.com/advice/star-interview-method", type: "article" }],
  prepRoadmap: PREP_ROADMAP,
  status: "draft",
  order: 10,
  createdAt: admin.firestore.FieldValue.serverTimestamp(),
  createdBy: "devert.contact@gmail.com",
});

let roundCount = 0, categoryCount = 0, questionCount = 0;
for (let ri = 0; ri < ROUNDS.length; ri++) {
  const round = ROUNDS[ri];
  const roundRef = await companyRef.collection("rounds").add({
    name: round.name, description: round.description, duration: round.duration, order: ri,
    whatTheyEvaluate: round.whatTheyEvaluate, format: round.format, eliminationCriteria: round.eliminationCriteria,
    prepStrategy: round.prepStrategy, commonMistakes: round.commonMistakes,
  });
  roundCount++;
  for (let ci = 0; ci < round.categories.length; ci++) {
    const category = round.categories[ci];
    const categoryRef = await roundRef.collection("categories").add({
      name: category.name, order: ci,
      whatYoullLearn: category.whatYoullLearn, concept: category.concept,
      keyPoints: category.keyPoints, commonMistakes: category.commonMistakes, interviewTips: category.interviewTips,
    });
    categoryCount++;
    for (let qi = 0; qi < category.questions.length; qi++) {
      await categoryRef.collection("questions").add({ ...category.questions[qi], order: qi });
      questionCount++;
    }
  }
}

for (let i = 0; i < INTERVIEW_EXPERIENCES.length; i++) {
  await companyRef.collection("interviewExperiences").add({ ...INTERVIEW_EXPERIENCES[i], order: i, submittedAt: admin.firestore.FieldValue.serverTimestamp() });
}

// Mock interviews reference (roundId, categoryId) pairs - resolved AFTER all
// rounds/categories are created above, since we need their real doc ids.
const roundSnap = await companyRef.collection("rounds").get();
const roundsByName = Object.fromEntries(roundSnap.docs.map(d => [d.data().name, d]));
async function categoryRefsFor(roundName, categoryNames) {
  const roundDoc = roundsByName[roundName];
  const catSnap = await roundDoc.ref.collection("categories").get();
  const byName = Object.fromEntries(catSnap.docs.map(d => [d.data().name, d.id]));
  return categoryNames.map(name => ({ roundId: roundDoc.id, categoryId: byName[name] })).filter(r => r.categoryId);
}

const MOCK_INTERVIEWS = [
  { name: "Technical Mock (Java + Spring Boot)", type: "technical", timeLimitMinutes: 25, refs: await categoryRefsFor("Technical Screening", ["Java Fundamentals", "OOP Concepts"]).then(async a => [...a, ...(await categoryRefsFor("Technical Interview", ["Spring Boot & REST APIs"]))]) },
  { name: "Coding Round Simulation", type: "coding", timeLimitMinutes: 30, refs: await categoryRefsFor("Coding Round", ["Programming Fundamentals & Output Prediction", "Data Structures & Algorithms Concepts", "SQL & Database Queries"]) },
  { name: "HR Discussion Mock", type: "hr", timeLimitMinutes: 15, refs: await categoryRefsFor("HR Discussion", ["HR & Behavioral Best Practices"]) },
];

let mockCount = 0;
for (let i = 0; i < MOCK_INTERVIEWS.length; i++) {
  const m = MOCK_INTERVIEWS[i];
  await companyRef.collection("mockInterviews").add({
    name: m.name, type: m.type, timeLimitMinutes: m.timeLimitMinutes, categoryRefs: m.refs, order: i, createdAt: admin.firestore.FieldValue.serverTimestamp(),
  });
  mockCount++;
}

console.log(`Seeded "Knowvation Learnings" (${companyRef.id}): ${roundCount} rounds, ${categoryCount} categories, ${questionCount} questions, ${INTERVIEW_EXPERIENCES.length} interview experiences, ${mockCount} mock interviews, ${PREP_ROADMAP.length}-day prep roadmap.`);
